result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/parser.py", "content": """"Recursive-descent parser producing a dataclass AST.

Grammar (kept exactly as specified):

    program = {stmt} ;
    stmt    = 'let' IDENT '=' expr ';'
            | IDENT '=' expr ';'
            | 'print' expr ';'
            | 'if' expr block [ 'else' block ]
            | 'while' expr block ;
    block   = '{' {stmt} '}' ;

    expr    = comparison ;                  -- comparison over additive over
    comparison = additive (('<'|'>'|'=='|'!=') additive)*      -- multiplicative
    additive   = mult (('+'|'-') mult)*                        -- over unary
    mult       = unary (('*'|'/') unary)*                      -- minus over
    unary      = '-' unary | primary                           -- primary
    primary    = INT | IDENT | '(' expr ')' ;
"""

from dataclasses import dataclass, field
from typing import Optional

from lexer import Token, tokenize


class ParseError(Exception):
    """Raised on syntax errors. Carries the line of the offending token."""

    def __init__(self, msg: str, line: int):
        super().__init__(f"line {line}: {msg}")
        self.msg = msg
        self.line = line


# --------------------------------------------------------------------------
# AST node definitions (dataclasses)
# --------------------------------------------------------------------------


@dataclass
class Expr:
    line: int  # every node knows the line it starts on


@dataclass
class IntLit(Expr):
    value: int


@dataclass
class Ident(Expr):
    name: str


@dataclass
class Unary(Expr):
    op: str          # '-'
    operand: Expr


@dataclass
class BinOp(Expr):
    op: str          # '<' '>' '==' '!=' '+' '-' '*' '/'
    left: Expr
    right: Expr


@dataclass
class Stmt:
    line: int


@dataclass
class LetStmt(Stmt):
    name: str
    expr: Expr


@dataclass
class AssignStmt(Stmt):
    name: str
    expr: Expr


@dataclass
class PrintStmt(Stmt):
    expr: Expr


@dataclass
class Block(Stmt):
    stmts: list = field(default_factory=list)


@dataclass
class IfStmt(Stmt):
    cond: Expr
    then: Block
    otherwise: Optional[Block]


@dataclass
class WhileStmt(Stmt):
    cond: Expr
    body: Block


@dataclass
class Program(Stmt):
    stmts: list = field(default_factory=list)


# --------------------------------------------------------------------------
# Parser
# --------------------------------------------------------------------------


class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    # -- helpers -----------------------------------------------------------

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != "EOF":
            self.pos += 1
        return tok

    def check(self, kind: str) -> bool:
        return self.peek().kind == kind

    def match(self, kind: str):
        if self.check(kind):
            return self.advance()
        return None

    def expect(self, kind: str, what: str) -> Token:
        tok = self.peek()
        if tok.kind != kind:
            raise ParseError(
                f"expected {what} ({kind}), got {tok.kind}"
                + (f" {tok.value!r}" if tok.value is not None else ""),
                tok.line,
            )
        return self.advance()

    # -- program / statements ----------------------------------------------

    def parse_program(self) -> Program:
        stmts = []
        while not self.check("EOF"):
            stmts.append(self.stmt())
        return Program(line=1, stmts=stmts)

    def stmt(self) -> Stmt:
        tok = self.peek()
        if tok.kind == "LET":
            return self.let_stmt()
        if tok.kind == "PRINT":
            return self.print_stmt()
        if tok.kind == "IF":
            return self.if_stmt()
        if tok.kind == "WHILE":
            return self.while_stmt()
        if tok.kind == "IDENT":
            return self.assign_stmt()
        raise ParseError(
            f"expected statement, got {tok.kind}"
            + (f" {tok.value!r}" if tok.value is not None else ""),
            tok.line,
        )

    def let_stmt(self) -> LetStmt:
        kw = self.expect("LET", "'let'")
        name_tok = self.expect("IDENT", "identifier after 'let'")
        self.expect("EQ_SINGLE_FALLBACK", "=") if False else self.expect_assign()
        expr = self.expr()
        self.expect("SEMI", "';'")
        return LetStmt(line=kw.line, name=name_tok.value, expr=expr)

    def expect_assign(self) -> Token:
        """Expect the single '=' of let/assignment ('==' is an error here)."""
        tok = self.peek()
        if tok.kind == "EQ":
            raise ParseError(
                "'==' used where '=' (assignment) was expected", tok.line
            )
        return self.expect("ASSIGN", "'='")

    def assign_stmt(self) -> AssignStmt:
        name_tok = self.expect("IDENT", "identifier")
        self.expect_assign()
        expr = self.expr()
        self.expect("SEMI", "';'")
        return AssignStmt(line=name_tok.line, name=name_tok.value, expr=expr)

    def print_stmt(self) -> PrintStmt:
        kw = self.expect("PRINT", "'print'")
        expr = self.expr()
        self.expect("SEMI", "';'")
        return PrintStmt(line=kw.line, expr=expr)

    def if_stmt(self) -> IfStmt:
        kw = self.expect("IF", "'if'")
        cond = self.expr()
        then = self.block()
        otherwise = None
        if self.match("ELSE"):
            otherwise = self.block()
        return IfStmt(line=kw.line, cond=cond, then=then, otherwise=otherwise)

    def while_stmt(self) -> WhileStmt:
        kw = self.expect("WHILE", "'while'")
        cond = self.expr()
        body = self.block()
        return WhileStmt(line=kw.line, cond=cond, body=body)

    def block(self) -> Block:
        lb = self.expect("LBRACE", "'{'")
        stmts = []
        while not self.check("RBRACE"):
            if self.check("EOF"):
                raise ParseError("unterminated block: missing '}'", self.peek().line)
            stmts.append(self.stmt())
        self.advance()  # consume '}'
        return Block(line=lb.line, stmts=stmts)

    # -- expressions ---------------------------------------------------------

    def expr(self) -> Expr:
        return self.comparison()

    def comparison(self) -> Expr:
        left = self.additive()
        while self.peek().kind in ("LT", "GT", "EQ", "NEQ"):
            op_tok = self.advance()
            right = self.additive()
            left = BinOp(line=op_tok.line, op=op_tok.value, left=left, right=right)
        return left

    def additive(self) -> Expr:
        left = self.multiplicative()
        while self.peek().kind in ("PLUS", "MINUS"):
            op_tok = self.advance()
            right = self.multiplicative()
            left = BinOp(line=op_tok.line, op=op_tok.value, left=left, right=right)
        return left

    def multiplicative(self) -> Expr:
        left = self.unary()
        while self.peek().kind in ("STAR", "SLASH"):
            op_tok = self.advance()
            right = self.unary()
            left = BinOp(line=op_tok.line, op=op_tok.value, left=left, right=right)
        return left

    def unary(self) -> Expr:
        if self.check("MINUS"):
            tok = self.advance()
            operand = self.unary()
            return Unary(line=tok.line, op="-", operand=operand)
        return self.primary()

    def primary(self) -> Expr:
        tok = self.peek()
        if tok.kind == "INT":
            self.advance()
            return IntLit(line=tok.line, value=tok.value)
        if tok.kind == "IDENT":
            self.advance()
            return Ident(line=tok.line, name=tok.value)
        if tok.kind == "LPAREN":
            self.advance()
            inner = self.expr()
            self.expect("RPAREN", "')'")
            return inner
        raise ParseError(
            f"expected expression, got {tok.kind}"
            + (f" {tok.value!r}" if tok.value is not None else ""),
            tok.line,
        )


def parse(src: str) -> Program:
    """Tokenize and parse source text, returning the Program AST."""
    return Parser(tokenize(src)).parse_program()
