result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/interp.py", "content": """"Tree-walking interpreter for the parsed AST.

Scoping rules:
  * There is a single top-level (global) scope.
  * Every block ('{' ... '}') creates a new nested scope when executed.
  * 'let' declares a name in the *current* (innermost) scope; redeclaring a
    name that already exists in the same scope is a runtime error.
  * Assignment requires the name to be declared in some enclosing scope; the
    innermost declaration is updated. Assigning to an undeclared name is a
    runtime error naming the identifier and the line.
  * Name lookup walks outward through the scope chain.

Values are integers. Comparison operators yield 1 (true) or 0 (false), and
any nonzero integer is truthy in conditions.
"""

from parser import (
    Program,
    Block,
    LetStmt,
    AssignStmt,
    PrintStmt,
    IfStmt,
    WhileStmt,
    IntLit,
    Ident,
    Unary,
    BinOp,
    parse,
)


class InterpError(Exception):
    """Runtime error. Carries message and line."""

    def __init__(self, msg: str, line: int):
        super().__init__(f"line {line}: {msg}")
        self.msg = msg
        self.line = line


class Interpreter:
    def __init__(self, out=None):
        import sys

        self.out = out if out is not None else sys.stdout
        self.scopes: list[dict] = [{}]  # scopes[0] is the global scope

    # -- entry points --------------------------------------------------------

    def run(self, source: str) -> None:
        self.execute(parse(source))

    def execute(self, program: Program) -> None:
        for stmt in program.stmts:
            self.exec_stmt(stmt)

    # -- statements ----------------------------------------------------------

    def exec_block(self, block: Block, new_scope: bool = True) -> None:
        if new_scope:
            self.scopes.append({})
        try:
            for stmt in block.stmts:
                self.exec_stmt(stmt)
        finally:
            if new_scope:
                self.scopes.pop()

    def exec_stmt(self, stmt) -> None:
        if isinstance(stmt, LetStmt):
            value = self.eval(stmt.expr)
            scope = self.scopes[-1]
            if stmt.name in scope:
                raise InterpError(
                    f"redeclaration of '{stmt.name}' in the same scope", stmt.line
                )
            scope[stmt.name] = value
        elif isinstance(stmt, AssignStmt):
            value = self.eval(stmt.expr)
            for scope in reversed(self.scopes):
                if stmt.name in scope:
                    scope[stmt.name] = value
                    return
            raise InterpError(
                f"assignment to undeclared variable '{stmt.name}'", stmt.line
            )
        elif isinstance(stmt, PrintStmt):
            print(self.eval(stmt.expr), file=self.out)
        elif isinstance(stmt, IfStmt):
            if self.eval(stmt.cond) != 0:
                self.exec_block(stmt.then)
            elif stmt.otherwise is not None:
                self.exec_block(stmt.otherwise)
        elif isinstance(stmt, WhileStmt):
            while self.eval(stmt.cond) != 0:
                self.exec_block(stmt.body)
        else:  # pragma: no cover - AST is closed
            raise InterpError(f"unknown statement {type(stmt).__name__}", stmt.line)

    # -- expressions -----------------------------------------------------------

    def eval(self, expr):
        if isinstance(expr, IntLit):
            return expr.value
        if isinstance(expr, Ident):
            for scope in reversed(self.scopes):
                if expr.name in scope:
                    return scope[expr.name]
            raise InterpError(f"undefined variable '{expr.name}'", expr.line)
        if isinstance(expr, Unary):  # '-'
            return -self.eval(expr.operand)
        if isinstance(expr, BinOp):
            left = self.eval(expr.left)
            right = self.eval(expr.right)
            op = expr.op
            if op == "<":
                return 1 if left < right else 0
            if op == ">":
                return 1 if left > right else 0
            if op == "==":
                return 1 if left == right else 0
            if op == "!=":
                return 1 if left != right else 0
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if op == "/":
                if right == 0:
                    raise InterpError("division by zero", expr.line)
                return int(left / right)  # truncate toward zero
        raise InterpError(  # pragma: no cover - AST is closed
            f"unknown expression node {type(expr).__name__}", expr.line
        )


def run(source: str, out=None) -> None:
    """Convenience helper: interpret `source`, printing output to `out`."""
    Interpreter(out=out).run(source)
